import SwiftUI

enum LoafieDesign {
    static let screenPadding: CGFloat = 20
    static let cardPadding: CGFloat = 16
    static let cardRadius: CGFloat = 12
    static let buttonRadius: CGFloat = 10
    static let fieldRadius: CGFloat = 8
    static let sectionSpacing: CGFloat = 24
}

extension Color {
    // Brand colors are generated by Xcode from the matching color assets.
    static let timerActive = Color.crustGold
    static let timerCompleted = Color.green
    static let timerPaused = Color.orange
    static let timerWarning = Color.red
}

struct LoafieCardModifier: ViewModifier {
    func body(content: Content) -> some View {
        content
            .padding(LoafieDesign.cardPadding)
            .background(Color.doughBeige)
            .clipShape(RoundedRectangle(cornerRadius: LoafieDesign.cardRadius, style: .continuous))
    }
}

extension View {
    func loafieCard() -> some View {
        modifier(LoafieCardModifier())
    }
}

struct LoafiePrimaryButtonStyle: ButtonStyle {
    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .font(.headline.weight(.semibold))
            .foregroundStyle(.white)
            .frame(maxWidth: .infinity)
            .padding(.vertical, 16)
            .background(Color.sourdoughBrown)
            .clipShape(RoundedRectangle(cornerRadius: LoafieDesign.buttonRadius, style: .continuous))
            .opacity(configuration.isPressed ? 0.8 : 1)
    }
}

struct LoafieSecondaryButtonStyle: ButtonStyle {
    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .font(.headline.weight(.semibold))
            .foregroundStyle(Color.sourdoughBrown)
            .frame(maxWidth: .infinity)
            .padding(.vertical, 16)
            .background(Color.doughBeige)
            .clipShape(RoundedRectangle(cornerRadius: LoafieDesign.buttonRadius, style: .continuous))
            .opacity(configuration.isPressed ? 0.7 : 1)
    }
}

struct LoafieDestructiveButtonStyle: ButtonStyle {
    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .font(.headline.weight(.semibold))
            .foregroundStyle(Color.red)
            .frame(maxWidth: .infinity)
            .padding(.vertical, 16)
            .background(Color.red.opacity(0.10))
            .clipShape(RoundedRectangle(cornerRadius: LoafieDesign.buttonRadius, style: .continuous))
            .opacity(configuration.isPressed ? 0.7 : 1)
    }
}

struct LoafieMark: View {
    var body: some View {
        Image(systemName: "bread.slices.fill")
            .symbolRenderingMode(.hierarchical)
            .foregroundStyle(Color.crustGold)
    }
}

@ViewBuilder
func stepIcon(for step: BakeStepType) -> some View {
    switch step {
    case .kneading:
        Image("KitchenCookingSymbol")
    case .bulkRoomTemperature:
        Image("KitchenDishSymbol")
    case .finalProofRoomTemperature:
        Image(systemName: "clock.fill")
    case .shaping:
        Image("Bread3Symbol")
    default:
        Image(systemName: step.symbolName)
    }
}
